content:
case PKT_SYMKEY_ENC:
      free_symkey_enc (pkt->pkt.symkey_enc);
      break;
    case PKT_PUBLIC_KEY:
    case PKT_PUBLIC_SUBKEY:
    case PKT_SECRET_KEY:
    case PKT_SECRET_SUBKEY:
      free_public_key (pkt->pkt.public_key);
      break;
    case PKT_COMMENT:
      free_comment (pkt->pkt.comment);
      break;
    case PKT_USER_ID:
      free_user_id (pkt->pkt.user_id);
      break;
    case PKT_COMPRESSED:
      free_compressed (pkt->pkt.compressed);
      break;
    case PKT_ENCRYPTED:
    case PKT_ENCRYPTED_MDC:
      free_encrypted (pkt->pkt.encrypted);
      break;
    case PKT_PLAINTEXT:
      free_plaintext (pkt->pkt.plaintext);
      break;
    default:
      xfree (pkt->pkt.generic);
      break;
    }

  pkt->pkt.generic = NULL;
}


/****************
 * returns 0 if they match.
 */
int
cmp_public_keys( PKT_public_key *a, PKT_public_key *b )
{
    int n, i;

    if( a->timestamp != b->timestamp )
        return -1;
    if( a->version < 4 && a->expiredate != b->expiredate )
        return -1;
    if( a->pubkey_algo != b->pubkey_algo )
        return -1;

    n = pubkey_get_npkey( b->pubkey_algo );
    if( !n ) { /* unknown algorithm, rest is in opaque MPI */
        if( mpi_cmp( a->pkey[0], b->pkey[0] ) )
            return -1; /* can't compare due to unknown algorithm */
    } else {
        for(i=0; i < n; i++ ) {
            if( mpi_cmp( a->pkey[i], b->pkey[i] ) )
                return -1;
        }
    }

    return 0;
}



int
cmp_signatures( PKT_signature *a, PKT_signature *b )
{
    int n, i;

    if( a->keyid[0] != b->keyid[0] )
        return -1;
    if( a->keyid[1] != b->keyid[1] )
        return -1;
    if( a->pubkey_algo != b->pubkey_algo )
        return -1;

    n = pubkey_get_nsig( a->pubkey_algo );
    if( !n )
        return -1; /* can't compare due to unknown algorithm */
    for(i=0; i < n; i++ ) {
        if( mpi_cmp( a->data[i] , b->data[i] ) )
            return -1;
    }
    return 0;
}
parse_plaintext (IOBUF inp, int pkttype, unsigned long pktlen,
                 PACKET * pkt, int new_ctb, int partial)
{
  int rc = 0;
  int mode, namelen;
  PKT_plaintext *pt;
  byte *p;
  int c, i;

  if (!partial && pktlen < 6)
    {
      log_error ("packet(%d) too short (%lu)\n", pkttype, (ulong) pktlen);
      if (list_mode)
        es_fputs (":literal data packet: [too short]\n", listfp);
      rc = gpg_error (GPG_ERR_INV_PACKET);
      goto leave;
    }
  mode = iobuf_get_noeof (inp);
  if (pktlen)
    pktlen--;
  namelen = iobuf_get_noeof (inp);
  if (pktlen)
    pktlen--;
  /* Note that namelen will never exceed 255 bytes. */
  pt = pkt->pkt.plaintext =
    xmalloc (sizeof *pkt->pkt.plaintext + namelen - 1);
  pt->new_ctb = new_ctb;
  pt->mode = mode;
  pt->namelen = namelen;
  pt->is_partial = partial;
  if (pktlen)
    {
      for (i = 0; pktlen > 4 && i < namelen; pktlen--, i++)
        pt->name[i] = iobuf_get_noeof (inp);
    }
  else
    {
      for (i = 0; i < namelen; i++)
        if ((c = iobuf_get (inp)) == -1)
          break;
        else
          pt->name[i] = c;
    }
  /* Fill up NAME so that a check with valgrind won't complain about
   * reading from uninitialized memory.  This case may be triggred by
   * corrupted packets.  */
  for (; i < namelen; i++)
    pt->name[i] = 0;

  pt->timestamp = read_32 (inp);
  if (pktlen)
    pktlen -= 4;
  pt->len = pktlen;
  pt->buf = inp;

  if (list_mode)
    {
      es_fprintf (listfp, ":literal data packet:\n"
                  "\tmode %c (%X), created %lu, name=\"",
                  mode >= ' ' && mode < 'z' ? mode : '?', mode,
                  (ulong) pt->timestamp);
      for (p = pt->name, i = 0; i < namelen; p++, i++)
        {
          if (*p >= ' ' && *p <= 'z')
            es_putc (*p, listfp);
          else
            es_fprintf (listfp, "\\x%02x", *p);
        }
      es_fprintf (listfp, "\",\n\traw data: ");
      if (partial)
